1234	// ---- 幂等辅助 ----
1235	
1236	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1237	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1238	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1239	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1240	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1241	func requestKey(operator, requestID string) string {
1242		b, _ := json.Marshal([2]string{operator, requestID})
1243		return string(b)
1244	}
1245	
1246	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1247	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1248	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1249	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1250	// 并回放。
1251	func isValidationErr(err error) bool {
1252		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1253	}
1254	
1255	var errCodes = map[error]string{
1256		ErrNotFound:             "not_found",
1257		ErrAlreadyExists:        "already_exists",
1258		ErrAccountInactive:      "account_inactive",
1259		ErrSeriesSealed:         "series_sealed",
1260		ErrConflict:             "conflict",
1261		ErrSameAccount:          "same_account",
1262		ErrForbidden:            "forbidden",
1263		ErrAuthorizationRevoked: "authorization_revoked",
1264		ErrAuthorizationExpired: "authorization_expired",
1265		ErrAuthorizationUsed:    "authorization_used",
1266		ErrRoyaltyFrozen:        "royalty_frozen",
1267		ErrSplitIntentRejected:  "split_intent_rejected",
1268		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1269		ErrSplitIntentInvalid:   "split_intent_invalid",
1270		ErrSplitIntentExpired:   "split_intent_expired",
1271		ErrSplitAnswered:        "split_answered",
1272	}
1273	
1274	var codeErrs = map[string]error{
1275		"not_found":              ErrNotFound,
1276		"already_exists":         ErrAlreadyExists,
1277		"account_inactive":       ErrAccountInactive,
1278		"series_sealed":          ErrSeriesSealed,
1279		"conflict":               ErrConflict,
1280		"same_account":           ErrSameAccount,
1281		"forbidden":              ErrForbidden,
1282		"authorization_revoked":  ErrAuthorizationRevoked,
1283		"authorization_expired":  ErrAuthorizationExpired,
1284		"authorization_used":     ErrAuthorizationUsed,
1285		"royalty_frozen":         ErrRoyaltyFrozen,
1286		"split_intent_rejected":  ErrSplitIntentRejected,
1287		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1288		"split_intent_invalid":   ErrSplitIntentInvalid,
1289		"split_intent_expired":   ErrSplitIntentExpired,
1290		"split_answered":         ErrSplitAnswered,
1291	}
1292	
1293	func errCode(err error) string {
1294		for sentinel, code := range errCodes {
1295			if errors.Is(err, sentinel) {
1296				return code
