630				_, proxyErr = r.ProxyTransfer(proxyReq("bob", "a1", "p1"))
631			}()
632			go func() {
633				defer wg.Done()
634				deactErr = r.DeactivateAccount("carol")
635			}()
636			wg.Wait()
637			if deactErr != nil {
638				t.Fatalf("deactivate: %v", deactErr)
639			}
640			h, _ := r.GetHolding("i1")
641			hist, _ := r.History("i1")
642			if proxyErr == nil {
643				if h.OwnerID != "carol" || h.Version != 2 || len(hist) != 2 {
644					t.Fatalf("proxy-first state wrong: %+v hist=%d", h, len(hist))
645				}
646			} else {
647				if !errors.Is(proxyErr, ErrAccountInactive) {
648					t.Fatalf("deactivate-first proxy must be inactive-rejected, got %v", proxyErr)
649				}
650				if h.OwnerID != "alice" || h.Version != 1 || len(hist) != 1 {
651					t.Fatalf("deactivate-first state wrong: %+v hist=%d", h, len(hist))
652				}
653			}
654		}
655	}
656	
657	// ---- 到期边界 ----
658	
659	func TestRevokeExpiredAuthorization(t *testing.T) {
660		r := mustCreate(t, tempDir(t))
661		authzWorld(t, r)
662		req := createAuthReq(r, "a1", time.Minute)
663		if _, err := r.CreateAuthorization(req); err != nil {
664			t.Fatal(err)
665		}
666		// 到期后仍未使用，授权人可以撤销：记录从 expired 变为 revoked
667		r.now = func() time.Time { return req.ExpiresAt.Add(time.Second) }
668		res, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
669			Operator: "alice", Reason: "到期后撤销", RequestID: "rv1", AuthID: "a1",
670		})
671		if err != nil || res.Status != AuthRevoked {
672			t.Fatalf("revoke expired-unused auth: %+v %v", res, err)
673		}
674		a, _ := r.GetAuthorization("a1")
675		if a.Status != AuthRevoked {
676			t.Fatalf("want revoked, got %s", a.Status)
677		}
678		evs, _ := r.AuthorizationHistory("i1")
679		if len(evs) != 2 || evs[1].FromStatus != AuthExpired || evs[1].ToStatus != AuthRevoked {
680			t.Fatalf("revoke event transition wrong: %+v", evs)
681		}
682	}
683	
684	func TestProxyRejectedWhenReceiverInactive(t *testing.T) {
685		r := mustCreate(t, tempDir(t))
686		authzWorld(t, r)
687		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
688			t.Fatal(err)
689		}
690		if err := r.DeactivateAccount("carol"); err != nil {
691			t.Fatal(err)
692		}
693		if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "p1")); !errors.Is(err, ErrAccountInactive) {
694			t.Fatalf("inactive receiver must block proxy, got %v", err)
695		}
696		h, _ := r.GetHolding("i1")
697		if h.OwnerID != "alice" || h.Version != 1 {
698			t.Fatalf("rejected proxy must not change holding: %+v", h)
699		}
700	}
701	
702	func TestExpiryBoundary(t *testing.T) {
703		r := mustCreate(t, tempDir(t))
704		authzWorld(t, r)
705		base := time.Unix(1_700_000_000, 0)
706		r.now = func() time.Time { return base }
707	
708		req := createAuthReq(r, "a1", time.Hour)
709		req.ExpiresAt = base.Add(time.Hour)
710		if _, err := r.CreateAuthorization(req); err != nil {
711			t.Fatal(err)
712		}
713		// 到期前一刻可用
714		r.now = func() time.Time { return base.Add(time.Hour - time.Nanosecond) }
715		if a, _ := r.GetAuthorization("a1"); a.Status != AuthActive {
716			t.Fatalf("just before expiry must be active, got %s", a.Status)
717		}
718		// 正好到期时间点起不可使用
719		r.now = func() time.Time { return base.Add(time.Hour) }
720		if a, _ := r.GetAuthorization("a1"); a.Status != AuthExpired {
721			t.Fatalf("at expiry must be expired, got %s", a.Status)
722		}
723		if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "p1")); !errors.Is(err, ErrAuthorizationExpired) {
724			t.Fatalf("proxy at expiry must fail expired, got %v", err)
725		}
726	}
727	
728	// ---- 持久化 ----
729	
730	func TestAuthorizationPersistenceAcrossReopen(t *testing.T) {
731		dir := tempDir(t)
732		r := mustCreate(t, dir)
733		authzWorld(t, r)
734		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", 24*time.Hour)); err != nil {
735			t.Fatal(err)
736		}
737		if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "p1")); err != nil {
738			t.Fatal(err)
739		}
740		// 代转后藏品在 carol（版本 2）手中，由 carol 再创建并撤销第二份授权
741		a2req := CreateAuthorizationRequest{
742			Operator: "carol", Reason: "委托2", RequestID: "create-a2", AuthID: "a2",
743			ItemID: "i1", TrusteeID: "bob", ToID: "alice",
744			ExpectedOwner: "carol", ExpectedVer: 2, ExpiresAt: r.now().Add(time.Hour),
745		}
746		if _, err := r.CreateAuthorization(a2req); err != nil {
747			t.Fatal(err)
748		}
749		if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
750			Operator: "carol", Reason: "撤销", RequestID: "rv1", AuthID: "a2",
751		}); err != nil {
752			t.Fatal(err)
753		}
754		if err := r.Close(); err != nil {
755			t.Fatal(err)
756		}
757	
758		r2, err := Open(dir)
759		if err != nil {
760			t.Fatalf("reopen: %v", err)
761		}
762		defer r2.Close()
763	
764		a1, err := r2.GetAuthorization("a1")
765		if err != nil || a1.Status != AuthUsed || a1.UsedTxSeq != 2 {
766			t.Fatalf("used auth must persist: %+v %v", a1, err)
767		}
768		a2, err := r2.GetAuthorization("a2")
769		if err != nil || a2.Status != AuthRevoked || a2.GranterID != "carol" {
770			t.Fatalf("revoked auth must persist: %+v %v", a2, err)
771		}
772		evs, err := r2.AuthorizationHistory("i1")
773		if err != nil || len(evs) != 4 {
774			t.Fatalf("auth events must persist: %d %v", len(evs), err)
775		}
776		hist, err := r2.History("i1")
777		if err != nil || len(hist) != 2 || hist[1].AuthID != "a1" || hist[1].Operator != "bob" {
778			t.Fatalf("proxy history must persist with trustee and auth trace: %+v %v", hist, err)
779		}
780		// 成功代转请求号重放
781		again, err := r2.ProxyTransfer(proxyReq("bob", "a1", "p1"))
782		if err != nil || !again.Replayed || again.TxSeq != 2 {
783			t.Fatalf("proxy replay across reopen: %+v %v", again, err)
784		}
785		// 已撤销授权重开后代转仍被拒
786		if _, err := r2.ProxyTransfer(proxyReq("bob", "a2", "p2")); !errors.Is(err, ErrAuthorizationRevoked) {
787			t.Fatalf("revoked auth still rejects after reopen: %v", err)
788		}
789	}
790	
791	// 旧版本写出的数据（没有授权字段）必须能直接打开，原历史不变。
792	func TestOpenSnapshotWithoutAuthorizationFields(t *testing.T) {
793		dir := tempDir(t)
794		r := mustCreate(t, dir)
795		setupWorld(t, r)
796		if _, err := r.Issue(issueReq("i1", "alice")); err != nil {
797			t.Fatal(err)
798		}
799		if _, err := r.Transfer(xferReq("alice", "i1", "bob", 1, "t1")); err != nil {
800			t.Fatal(err)
801		}
802		if err := r.Close(); err != nil {
803			t.Fatal(err)
804		}
805	
806		// 读入旧格式快照（删除新字段后即为旧格式），确认仍可打开。
807		b, err := os.ReadFile(filepath.Join(dir, "registry.json"))
808		if err != nil {
809			t.Fatal(err)
810		}
811		for _, key := range []string{`"authzs"`, `"auth_events"`, `"next_auth_seq"`, `"auth_id"`} {
812			if bytes.Contains(b, []byte(key)) {
813				t.Fatalf("baseline snapshot should not contain %s", key)
814			}
815		}
816		r2, err := Open(dir)
817		if err != nil {
818			t.Fatalf("old snapshot must open: %v", err)
819		}
820		defer r2.Close()
821		hist, _ := r2.History("i1")
822		if len(hist) != 2 || hist[1].AuthID != "" {
823			t.Fatalf("original history unchanged: %+v", hist)
824		}
825		if evs, err := r2.AuthorizationHistory("i1"); err != nil || len(evs) != 0 {
826			t.Fatalf("old item has empty auth history: %v %v", evs, err)
827		}
828		// 打开后新功能可正常使用（当前持有人为 bob，版本 2）
829		if err := r2.RegisterAccount("carol", "接收人"); err != nil {
830			t.Fatal(err)
831		}
832		newReq := CreateAuthorizationRequest{
833			Operator: "bob", Reason: "委托", RequestID: "ca1", AuthID: "a1",
834			ItemID: "i1", TrusteeID: "alice", ToID: "carol",
835			ExpectedOwner: "bob", ExpectedVer: 2, ExpiresAt: r2.now().Add(time.Hour),
836		}
837		if _, err := r2.CreateAuthorization(newReq); err != nil {
838			t.Fatalf("new feature works on opened old registry: %v", err)
839		}
840	}
