33	// setupBatchTransferWorld 发行 i1..i5（历史序号 1..5）后，再由 alice 发行
34	// i6（s1，序号 6）给 bob，并由 bob 以 10000 分把 i6 转让给 alice（序号 7）。
35	// 因此失败发生前最后一条历史序号是 7；carol/dave 各有一条序号 7 的应付
36	// （1000/500），余款 8500 归 bob。清单外藏品 i4（bob，版本 1）、i5
37	// （carol，版本 1）与已易手的 i6（alice，版本 2）用于核对失败不外溢。
38	func seedBatchSaveFailureWorld(t *testing.T, r *Registry) {
