package registry

import (
	"errors"
	"reflect"
	"testing"
)

// 本文件为单件转让补充"拒绝结果保存失败"场景的回归保障，与整批转让
// （batch_transfer_save_failure_test.go）行为对齐：状态类业务拒绝（持有
// 信息不符、账户停用、收发同人）在落盘失败时，必须返回保存错误而非业务
// 错误，结果为空，请求号与历史序号都不被这次未保存的拒绝消耗；保存条件
// 恢复后用完全相同的请求重提，按当时的业务状态重新判断——拒绝条件仍在
// 则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则正常转出。
//
// 失败注入方式与整批共用：在临时文件路径 .registry.json.tmp 上预先建一个
// 目录，save 在 OpenFile 阶段即以 EISDIR 失败，原快照完好可读。

// xferSaveReq 构造 bob 发起的单件转让请求。
func xferSaveReq(rid, item, expectedOwner string, ver int64, to string, price int64) TransferRequest {
	return TransferRequest{
		Operator: "bob", Reason: "转出", RequestID: rid, ItemID: item,
		ExpectedOwner: expectedOwner, ExpectedVer: ver, ToID: to, Price: price,
	}
}

// assertTransferSaveFailureEmpty 核对"拒绝结果保存失败"的返回：error 是
// 保存错误而非任何业务拒绝；结果为空——不携带藏品编号、前后持有人、版本、
// 历史序号或金额，业务错误为空，也不标记为重复返回。
func assertTransferSaveFailureEmpty(t *testing.T, res TransferResult, err error) {
	t.Helper()
	assertSaveFailureError(t, err)
	if res.ItemID != "" || res.FromID != "" || res.ToID != "" ||
		res.Version != 0 || res.TxSeq != 0 || res.Replayed || res.Err != nil ||
		res.Price != 0 || res.Payables != nil || res.Remainder != 0 {
		t.Fatalf("拒绝保存失败必须返回空结果: %+v", res)
	}
}

// assertXferRequestFree 核对请求号未被这次未保存的拒绝占用、历史序号未被
// 消耗（在同一个已打开的登记册上检查）。
func assertXferRequestFree(t *testing.T, r *Registry, req TransferRequest, wantNextSeq int64) {
	t.Helper()
	if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
		t.Fatalf("未保存的拒绝不应占用请求号 %s", req.RequestID)
	}
	if r.state.NextSeq != wantNextSeq {
		t.Fatalf("NextSeq = %d, want %d", r.state.NextSeq, wantNextSeq)
	}
}

// assertHoldingUnchanged 核对藏品持有与历史保持提交前内容。
func assertHoldingUnchanged(t *testing.T, r *Registry, itemID, owner string, ver int64, histLen int) {
	t.Helper()
	h, err := r.GetHolding(itemID)
	if err != nil {
		t.Fatalf("GetHolding %s: %v", itemID, err)
	}
	if h.OwnerID != owner || h.Version != ver {
		t.Fatalf("失败后 %s 持有被改变: %+v", itemID, h)
	}
	hist, err := r.History(itemID)
	if err != nil {
		t.Fatalf("History %s: %v", itemID, err)
	}
	if len(hist) != histLen {
		t.Fatalf("失败后 %s 历史多出内容: %+v", itemID, hist)
	}
}

// TestTransferRejectSaveFailureRetrySameState 覆盖：持有信息不符的拒绝落盘
// 失败时返回保存错误、结果为空、请求号不被占用；保存恢复且拒绝条件仍在时，
// 用完全相同的请求重提会重新保存此次拒绝，保存成功后才返回业务错误；此后
// 相同请求回放该拒绝。
func TestTransferRejectSaveFailureRetrySameState(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupBatchTransferWorld(t, r)
	// i5 属于 carol（版本 1），与期望的 bob 不符：ErrConflict。
	req := xferSaveReq("rt-rej", "i5", "bob", 1, "dave", 200)

package registry

import "errors"

// 错误哨兵。业务拒绝与参数错误使用包裹这些哨兵的错误，调用方可用
// errors.Is 判定；返回结果中的 Err 字段同样包裹这些哨兵。
var (
	// ErrNotFound 表示查询或引用的账户、系列或藏品不存在。
	ErrNotFound = errors.New("registry: 对象不存在")

	// ErrAlreadyExists 表示账户、系列或藏品编号已被占用。
	ErrAlreadyExists = errors.New("registry: 对象已存在")

	// ErrAccountInactive 表示账户已停用，不能参与新的发行或转让。
	ErrAccountInactive = errors.New("registry: 账户已停用")

	// ErrSeriesSealed 表示系列已封存，不能继续发行；封存不可撤销。
	ErrSeriesSealed = errors.New("registry: 系列已封存")

	// ErrConflict 表示乐观并发冲突：藏品持有人或期望版本与当前状态不符。
	ErrConflict = errors.New("registry: 持有人或版本不符，转让被拒绝")

	// ErrSameAccount 表示转让的发起人与接收人相同。
	ErrSameAccount = errors.New("registry: 转让发起人与接收人不能相同")

	// ErrForbidden 表示操作者无权执行该操作（例如非系列创建账户发行或封存、
	// 非授权人撤销授权、非受托人发起代转）。
	ErrForbidden = errors.New("registry: 操作者无权执行该操作")

	// ErrAuthorizationRevoked 表示代转授权已被授权人撤销，不能再用于代转。
	ErrAuthorizationRevoked = errors.New("registry: 授权已撤销")

	// ErrAuthorizationExpired 表示代转授权已过绝对到期时间，从到期时间点
	// 起不可再使用。
	ErrAuthorizationExpired = errors.New("registry: 授权已过期")

	// ErrAuthorizationUsed 表示一次性代转授权已被使用（或对已使用的授权
	// 请求撤销）。
	ErrAuthorizationUsed = errors.New("registry: 授权已使用")

	// ErrRoyaltyFrozen 表示系列已成功发行首件藏品，版税规则已固定，
	// 不能再设置或清空。
	ErrRoyaltyFrozen = errors.New("registry: 版税规则已固定")

	// ErrSplitIntentRejected 表示拆分意向已被参与账户拒绝，不再接受答复，
	// 也不能撤回。
	ErrSplitIntentRejected = errors.New("registry: 拆分意向已拒绝")

	// ErrSplitIntentWithdrawn 表示拆分意向已被发起人撤回，不再接受答复。
	ErrSplitIntentWithdrawn = errors.New("registry: 拆分意向已撤回")

	// ErrSplitIntentInvalid 表示拆分意向已失效：藏品持有版本已变化，或
	// 发起人、任一参与账户已停用；失效不可恢复。
	ErrSplitIntentInvalid = errors.New("registry: 拆分意向已失效")

	// ErrSplitIntentExpired 表示拆分意向已过绝对到期时间，从到期时间点
	// 起不再接受答复或撤回。
	ErrSplitIntentExpired = errors.New("registry: 拆分意向已过期")

	// ErrSplitAnswered 表示参与账户已作出不同答复，不能改答。
	ErrSplitAnswered = errors.New("registry: 已作出不同答复，不能改答")

	// ErrRequestConflict 表示请求号已被同一操作者使用，但本次业务参数不同。
	ErrRequestConflict = errors.New("registry: 请求号冲突")

	// ErrInvalidArgument 表示必填内容缺失或参数不合法。
	ErrInvalidArgument = errors.New("registry: 参数不合法")

	// ErrCorrupt 表示登记册数据已存在但无法读取或解析。
	ErrCorrupt = errors.New("registry: 登记册数据无法读取")

	// ErrLocked 表示登记册正被另一个进程以独占方式使用。
	ErrLocked = errors.New("registry: 登记册已被占用")
)

