324	// 已过期意向的撤回本应返回对应哨兵错误，但拒绝结果保存失败时返回实际保存
325	// 错误、结果为空、不占用请求号；意向原有的落盘/派生状态与结束时间保持
326	// 不变。恢复后原请求重提重新保存对应拒绝（首次不标回放），再次提交才回放。
327	func TestWithdrawSplitIntentEndedStatusSaveFailure(t *testing.T) {
328		t.Run("rejected", func(t *testing.T) {
