330			answerSaveFailureWorld(t, r)
331			// carol 拒绝，方案终结为已拒绝（已保存，结束时间已写入）。
332			if _, err := r.AnswerSplitIntent(answerReq("carol", "it1", "ans-carol", false)); err != nil {
