337	
338			blockBatchSave(t, r)
339			res, err := r.WithdrawSplitIntent(req)
340			assertWithdrawSaveFailureEmpty(t, res, err)
341			assertWithdrawRequestFree(t, r, req, 2)
342			// 原已拒绝状态与结束时间保持不变。
343			assertIntentParties(t, r, "it1", SplitRejected, map[string]string{
344				"carol": SplitAnswerReject,
345			}, true)
346	
347			restoreBatchSave(t, r)
348			res, err = r.WithdrawSplitIntent(req)
349			if !errors.Is(err, ErrSplitIntentRejected) {
350				t.Fatalf("重提应返回 ErrSplitIntentRejected: %v", err)
351			}
352			if res.Replayed || res.IntentID != "it1" || !errors.Is(res.Err, ErrSplitIntentRejected) {
353				t.Fatalf("已拒绝意向撤回的重提结果异常: %+v", res)
354			}
355			res, err = r.WithdrawSplitIntent(req)
356			if !errors.Is(err, ErrSplitIntentRejected) || !res.Replayed {
357				t.Fatalf("再次提交应回放已保存的拒绝: %+v, err %v", res, err)
358			}
359			after, _ := r.GetSplitIntent("it1")
360			if !after.EndedAt.Equal(before.EndedAt) {
361				t.Fatalf("结束时间不应被失败请求改变: before %v after %v", before.EndedAt, after.EndedAt)
362			}
363		})
364	
365		t.Run("invalid", func(t *testing.T) {
366			r := mustCreate(t, tempDir(t))
367			answerSaveFailureWorld(t, r)
368			// alice 把 i1 合法转给 dave：持有版本变为 2，意向失效。
369			if _, err := r.Transfer(xferReq("alice", "i1", "dave", 1, "rt-move")); err != nil {
370				t.Fatal(err)
371			}
372			req := withdrawReq("alice", "it1", "wd-invalid")
373	
374			blockBatchSave(t, r)
375			res, err := r.WithdrawSplitIntent(req)
376			assertWithdrawSaveFailureEmpty(t, res, err)
377			assertWithdrawRequestFree(t, r, req, 1)
378			assertIntentParties(t, r, "it1", SplitInvalid, map[string]string{"bob": ""}, false)
379	
380			restoreBatchSave(t, r)
381			res, err = r.WithdrawSplitIntent(req)
382			if !errors.Is(err, ErrSplitIntentInvalid) {
383				t.Fatalf("重提应返回 ErrSplitIntentInvalid: %v", err)
384			}
385			if res.Replayed || res.IntentID != "it1" || !errors.Is(res.Err, ErrSplitIntentInvalid) {
386				t.Fatalf("已失效意向撤回的重提结果异常: %+v", res)
387			}
388			// 失效拒绝不写入结束时间、不新增历史。
389			assertIntentParties(t, r, "it1", SplitInvalid, map[string]string{"bob": ""}, false)
390			if evs, _ := r.SplitIntentHistory("i1"); len(evs) != 1 {
391				t.Fatalf("失效拒绝不应新增意向历史: %+v", evs)
392			}
393			res, err = r.WithdrawSplitIntent(req)
394			if !errors.Is(err, ErrSplitIntentInvalid) || !res.Replayed ||
395				!errors.Is(res.Err, ErrSplitIntentInvalid) {
396				t.Fatalf("再次提交应回放已保存的失效拒绝: %+v, err %v", res, err)
397			}
398		})
399	
400		t.Run("expired", func(t *testing.T) {
401			r := mustCreate(t, tempDir(t))
402			intentWorld(t, r)
403			base := time.Unix(2_100_000_000, 0)
404			r.now = func() time.Time { return base }
405			defer func() { r.now = time.Now }()
406			if _, err := r.CreateSplitIntent(createIntentReq(r, "it1")); err != nil {
407				t.Fatal(err)
408			}
409			req := withdrawReq("alice", "it1", "wd-expired")
410	
411			blockBatchSave(t, r)
412			// 时间走到到期点：意向已过期。
413			r.now = func() time.Time { return base.Add(time.Hour) }
414			res, err := r.WithdrawSplitIntent(req)
415			assertWithdrawSaveFailureEmpty(t, res, err)
416			assertWithdrawRequestFree(t, r, req, 1)
