438	// TestWithdrawSplitIntentRepeatWithdrawSaveFailure 覆盖：对已撤回意向再次
439	// 撤回（幂等路径）只登记请求结果、不新增变更记录；该请求结果保存失败时
440	// 同样返回实际保存错误、结果为空、不占用请求号，原撤回状态与历史保持
441	// 不变；恢复后重提首次正常返回已撤回（不标回放、不新增历史），此后回放。
442	func TestWithdrawSplitIntentRepeatWithdrawSaveFailure(t *testing.T) {
443		r := mustCreate(t, tempDir(t))
444		answerSaveFailureWorld(t, r)
445		// 首次撤回已保存：历史为 create + withdraw，序号 2。
446		if _, err := r.WithdrawSplitIntent(withdrawReq("alice", "it1", "wd-1")); err != nil {
447			t.Fatal(err)
