527	// TestWithdrawSplitIntentSaveFailureRetryInvalid 覆盖：撤回保存失败后持有
528	// 版本发生变化（藏品被合法转出）使意向失效的，原请求重提沿用现有的失效
529	// 拒绝，不回放未保存的撤回；失效后当前持有人可用新编号另建方案。
530	func TestWithdrawSplitIntentSaveFailureRetryInvalid(t *testing.T) {
531		r := mustCreate(t, tempDir(t))
532		answerSaveFailureWorld(t, r)
533		req := withdrawReq("alice", "it1", "wd-1")
534	
535		blockBatchSave(t, r)
