554		}
555		// 方案没有被撤回：当前派生状态为已失效，无结束时间，历史无撤回。
556		assertIntentParties(t, r, "it1", SplitInvalid, map[string]string{"bob": ""}, false)
557		if evs, _ := r.SplitIntentHistory("i1"); len(evs) != 1 {
558			t.Fatalf("失效拒绝不应新增意向历史: %+v", evs)
559		}
560		// 该拒绝保存后，相同请求回放首次（失效）拒绝。
561		res, err = r.WithdrawSplitIntent(req)
562		if !errors.Is(err, ErrSplitIntentInvalid) || !res.Replayed ||
563			!errors.Is(res.Err, ErrSplitIntentInvalid) {
564			t.Fatalf("保存后的再次提交应回放失效拒绝: %+v, err %v", res, err)
565		}
566	}
567	
568	// TestWithdrawSplitIntentSaveFailureAfterReopen 覆盖磁盘视角：原数据可读时
569	// 保存失败后关闭重开，看到的仍是撤回前状态——未保存的撤回不存在、请求号
570	// 未占用；恢复保存后用原请求重提正常撤回。
571	func TestWithdrawSplitIntentSaveFailureAfterReopen(t *testing.T) {
572		dir := tempDir(t)
573		r := mustCreate(t, dir)
574		answerSaveFailureWorld(t, r)
575		req := withdrawReq("alice", "it1", "wd-1")
576	
577		blockBatchSave(t, r)
578		res, err := r.WithdrawSplitIntent(req)
579		assertWithdrawSaveFailureEmpty(t, res, err)
580	
581		if err := r.Close(); err != nil {
582			t.Fatal(err)
583		}
584		r2, err := Open(dir)
585		if err != nil {
586			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
587		}
588		t.Cleanup(func() { _ = r2.Close() })
589		assertIntentParties(t, r2, "it1", SplitPending, map[string]string{
590			"alice": SplitAnswerAgree, "bob": "", "carol": "",
591		}, false)
592		if _, ok := r2.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
593			t.Fatal("重开后未保存的撤回不应占用请求号")
594		}
595		if r2.state.NextIntentSeq != 1 {
596			t.Fatalf("重开后 NextIntentSeq = %d, want 1", r2.state.NextIntentSeq)
597		}
598		if evs, _ := r2.SplitIntentHistory("i1"); len(evs) != 1 {
599			t.Fatalf("重开后历史应只有创建: %+v", evs)
600		}
601	
602		restoreBatchSave(t, r2)
603		res2, err := r2.WithdrawSplitIntent(req)
604		if err != nil || res2.Replayed || res2.Status != SplitWithdrawn {
605			t.Fatalf("重开后重提应正常撤回: %+v, err %v", res2, err)
606		}
607		res2, err = r2.WithdrawSplitIntent(req)
608		if err != nil || !res2.Replayed || res2.Status != SplitWithdrawn {
609			t.Fatalf("成功后重提应回放: %+v, err %v", res2, err)
610		}
611	}
612	
613	// TestWithdrawSplitIntentValidationIgnoresSaveFailure 覆盖：必填内容缺失与
614	// 意向不存在的请求不占用请求号、不要求保存，即使数据位置暂时不可写也仍
615	// 返回原参数/引用错误，不能改报保存错误。
616	func TestWithdrawSplitIntentValidationIgnoresSaveFailure(t *testing.T) {
617		r := mustCreate(t, tempDir(t))
618		answerSaveFailureWorld(t, r)
619	
620		blockBatchSave(t, r)
621		defer restoreBatchSave(t, r)
622	
623		// 必填内容缺失：返回 ErrInvalidArgument，不是保存错误。
624		if _, err := r.WithdrawSplitIntent(WithdrawSplitIntentRequest{}); !errors.Is(err, ErrInvalidArgument) {
625			t.Fatalf("必填缺失应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
626		}
627		missing := withdrawReq("alice", "it1", "wd-miss")
628		missing.IntentID = ""
629		if _, err := r.WithdrawSplitIntent(missing); !errors.Is(err, ErrInvalidArgument) {
630			t.Fatalf("必填缺失应返回 ErrInvalidArgument: %v", err)
631		}
632	
633		// 引用不存在的意向：返回 ErrNotFound，不是保存错误。
634		notFoundReq := withdrawReq("alice", "it-nf", "wd-nf")
635		res, err := r.WithdrawSplitIntent(notFoundReq)
636		if !errors.Is(err, ErrNotFound) {
637			t.Fatalf("引用不存在应返回 ErrNotFound，不能改报保存错误: %v", err)
638		}
639		if res.IntentID != "it-nf" || !errors.Is(res.Err, ErrNotFound) {
640			t.Fatalf("引用不存在的结果异常: %+v", res)
641		}
642	
643		// 两类请求都不占用请求号，意向历史序号也不消耗。
644		if _, ok := r.state.Requests[requestKey("alice", "wd-nf")]; ok {
645			t.Fatal("引用不存在不应占用请求号")
646		}
647		if r.state.NextIntentSeq != 1 {
648			t.Fatalf("NextIntentSeq = %d, want 1", r.state.NextIntentSeq)
649		}
650	}
