	if err := r.CreateSeries("s1", "alice", "首批系列"); err != nil {
		t.Fatal(err)
	}
}

func issueReq(item, holder string) IssueRequest {
	return IssueRequest{
		Operator: "alice", Reason: "首发", RequestID: "req-" + item,
